// The spine: the brief's VO text (verbatim) and the target scene lengths in seconds.
export const SCENES = [
  { id: 'S01', title: 'End of life', target: 9, vo: 'On the seventh of April, Django four-point-two reached end of life. No more security fixes.' },
  { id: 'S02', title: 'Still shipped', target: 12, vo: 'But Debian thirteen and Ubuntu twenty-four-oh-four still ship it. Since then, Django has published nineteen security advisories — and not one official patch for four-point-two.' },
  { id: 'S03', title: 'The finding', target: 20, vo: "On October first, Ubuntu shipped a backport for one of them. Five days later, Django said its original fix was incomplete. We took Ubuntu's source package, ran a test calibrated on Django's own fix commits… and the code path Django closed is still reachable in Ubuntu's build." },
  { id: 'S04', title: 'Heirloom', target: 11, vo: 'That test was run by Heirloom — an agent that keeps end-of-life software patched, and proves which old versions are actually vulnerable.' },
  { id: 'S05', title: 'The method', target: 19, vo: "Its first rule: never trust a test that hasn't failed. For each advisory, Heirloom writes its own test, proves it fails on Django's vulnerable code and passes on the fix… and only then asks the real question: is the old version affected?" },
  { id: 'S06', title: 'The campaign', target: 28, vo: 'Then we let it run the whole campaign: nineteen advisories, replayed in the order Django published them. Thirteen candidate backports — each one failing before the fix, and passing after. Where it couldn\'t prove something, it filed the evidence instead of guessing. And when a new fix amended one it had already backported, it stacked the follow-up on its own pull request.' },
  { id: 'S07', title: 'One question', target: 17, vo: 'Across the whole campaign, it asked me one question — a real judgement call about changing Django\'s behaviour. I answered once. It sealed the answer as a precedent, and the next case reused it without asking.' },
  { id: 'S08', title: 'Proof', target: 23, vo: 'We tested the method on cases with known answers. A naive pipeline once called a vulnerable version safe. Heirloom: zero times. Every claim in every pull request links to its neat-logs trace, and every backport links the Entire session of the agent that wrote it.' },
  { id: 'S09', title: 'Economics', target: 11, vo: "Each advisory cost about twenty cents of model time. We modelled the business in C-F-O dot A-I: what that's worth to the teams who keep old software alive." },
  { id: 'S10', title: 'Kept honest', target: 15, vo: 'Heirloom. Old software, kept honest. Every verdict is a test run you can open.' },
];
export const FPS = 60;
export const HEAD = 0.4;
export const TAIL = 0.6;
export const END_HOLD = 4;
// Renders the deliverables into ~/video-out (or $VIDEO_OUT):
//   scenes/S01.mp4…S10.mp4 (silent) → concat (stream copy) → master/HeirloomDemo-silent.mp4
//   master/HeirloomDemo-captions.mp4 (burned captions), master/HeirloomDemo.srt
//   master/HeirloomDemo-mix.mp4 when public/audio/vo/*.mp3 exist; stills/S01.png…
// Usage: node scripts/render.mjs [scenes|master|captions|mix|stills|all]…  (default: all)
import { bundle } from '@remotion/bundler';
import { renderMedia, renderStill, selectComposition } from '@remotion/renderer';
import { execFileSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const OUT = process.env.VIDEO_OUT ?? join(homedir(), 'video-out');
const args = process.argv.slice(2);
const only = (args.find((a) => a.startsWith('--scenes=')) ?? '').replace('--scenes=', '').split(',').filter(Boolean);
const steps = new Set(args.filter((a) => !a.startsWith('--')).length ? args.filter((a) => !a.startsWith('--')) : ['all']);
const want = (s) => steps.has('all') || steps.has(s);
const timing = JSON.parse(readFileSync(join(root, 'timing.json'), 'utf8'));
for (const d of ['master', 'scenes', 'stills']) mkdirSync(join(OUT, d), { recursive: true });

const t0 = Date.now();
const log = (...a) => console.log(`[${((Date.now() - t0) / 1000).toFixed(0).padStart(5)}s]`, ...a);

const serveUrl = await bundle({ entryPoint: join(root, 'src/index.ts'), publicDir: join(root, 'public') });
log('bundled');
const common = { codec: 'h264', crf: 14, x264Preset: 'slow', pixelFormat: 'yuv420p', colorSpace: 'bt709', concurrency: Number(process.env.CONC ?? 8), imageFormat: 'jpeg', jpegQuality: 95 };
const comp = async (inputProps) => selectComposition({ serveUrl, id: 'HeirloomDemo', inputProps });

const silentProps = { captions: false, audio: false };
if (want('scenes') || want('master')) {
  const composition = await comp(silentProps);
  for (const s of timing.scenes) {
    if (only.length && !only.includes(s.id)) continue;
    const out = join(OUT, 'scenes', `${s.id}.mp4`);
    let last = 0;
    await renderMedia({
      ...common,
      composition,
      serveUrl,
      inputProps: silentProps,
      outputLocation: out,
      frameRange: [s.start, s.start + s.frames - 1],
      muted: true,
      onProgress: ({ progress }) => {
        if (progress - last > 0.25) { last = progress; log(`${s.id} ${(progress * 100).toFixed(0)}%`); }
      },
    });
    log(`scene ${s.id} done`);
  }
}
if (want('master')) {
  const missing = timing.scenes.filter((s) => !existsSync(join(OUT, 'scenes', `${s.id}.mp4`)));
  if (missing.length) throw new Error(`missing scenes: ${missing.map((s) => s.id)}`);
  const list = join(OUT, 'scenes', 'concat.txt');
  writeFileSync(list, timing.scenes.map((s) => `file '${join(OUT, 'scenes', `${s.id}.mp4`)}'`).join('\n') + '\n');
  execFileSync('ffmpeg', ['-v', 'error', '-y', '-f', 'concat', '-safe', '0', '-i', list, '-c', 'copy', '-movflags', '+faststart', join(OUT, 'master', 'HeirloomDemo-silent.mp4')]);
  log('master/HeirloomDemo-silent.mp4');
}

copyFileSync(join(root, 'captions.srt'), join(OUT, 'master', 'HeirloomDemo.srt'));

const master = join(OUT, 'master', 'HeirloomDemo-silent.mp4');
if (want('captions')) {
  // captions alone on transparency, then overlaid on the silent master (one x264 pass, no second full render)
  const layer = join(root, 'out', 'captions-layer.mov');
  const composition = await selectComposition({ serveUrl, id: 'CaptionsLayer', inputProps: {} });
  await renderMedia({ composition, serveUrl, codec: 'prores', proresProfile: '4444', imageFormat: 'png', pixelFormat: 'yuva444p10le', concurrency: 8, outputLocation: layer, muted: true });
  log('captions layer');
  execFileSync('ffmpeg', ['-v', 'error', '-y', '-i', master, '-i', layer, '-filter_complex', '[0:v][1:v]overlay=0:0:format=auto,format=yuv420p', '-c:v', 'libx264', '-preset', 'slow', '-crf', '14', '-profile:v', 'high', '-colorspace', 'bt709', '-color_primaries', 'bt709', '-color_trc', 'bt709', '-movflags', '+faststart', '-an', join(OUT, 'master', 'HeirloomDemo-captions.mp4')]);
  log('master/HeirloomDemo-captions.mp4');
}

const vo = existsSync(join(root, 'public/audio/vo')) && readdirSync(join(root, 'public/audio/vo')).some((f) => f.endsWith('.mp3'));
if (want('mix') && vo) {
  // audio only (VO, music bed with ducking, SFX), muxed onto the silent master's picture without re-encoding
  const props = { captions: false, audio: true };
  const composition = await comp(props);
  const wav = join(root, 'out', 'mix.wav');
  await renderMedia({ composition, serveUrl, inputProps: props, codec: 'wav', outputLocation: wav, concurrency: 8 });
  execFileSync('ffmpeg', ['-v', 'error', '-y', '-i', master, '-i', wav, '-map', '0:v', '-map', '1:a', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '320k', '-ar', '48000', '-shortest', '-movflags', '+faststart', join(OUT, 'master', 'HeirloomDemo-mix.mp4')]);
  log('master/HeirloomDemo-mix.mp4');
} else if (want('mix')) log('mix skipped: no VO files in public/audio/vo');

if (want('stills')) {
  const KEY = { S01: 6.6, S02: 10.6, S03: 18.6, S04: 5.8, S05: 10.8, S06: 10.4, S07: 11.8, S08: 8.8, S09: 3.2, S10: 12.5 };
  const composition = await comp(silentProps);
  for (const s of timing.scenes) {
    const frame = s.start + Math.min(s.frames - 1, Math.round(KEY[s.id] * 60 * s.scale));
    await renderStill({ composition, serveUrl, inputProps: silentProps, frame, output: join(OUT, 'stills', `${s.id}.png`), imageFormat: 'png' });
  }
  log('stills');
}
log('done');
// Renders review stills in one bundle: node scripts/stills.mjs [outDir] [S01:4.5 S03:12 …]
// Default: the key moment of every scene (KEY below, seconds into the scene, scaled with the retime).
import { bundle } from '@remotion/bundler';
import { renderStill, selectComposition } from '@remotion/renderer';
import { mkdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const timing = JSON.parse(readFileSync(join(root, 'timing.json'), 'utf8'));
export const KEY = { S01: [6.6], S02: [10.6], S03: [11.6, 18.6], S04: [5.8], S05: [10.8, 14.2], S06: [10.4], S07: [11.8], S08: [8.8], S09: [3.2], S10: [12.5] };

const outDir = process.argv[2] ?? join(root, 'out/stills');
const args = process.argv.slice(3);
const want = args.length
  ? args.map((a) => { const [id, s] = a.split(':'); return [id, Number(s)]; })
  : Object.entries(KEY).flatMap(([id, ss]) => ss.map((s) => [id, s]));
const captions = process.env.CAPTIONS === '1';

mkdirSync(outDir, { recursive: true });
const serveUrl = await bundle({ entryPoint: join(root, 'src/index.ts'), publicDir: join(root, 'public') });
const inputProps = { captions, audio: false };
const composition = await selectComposition({ serveUrl, id: 'HeirloomDemo', inputProps });
for (const [id, s] of want) {
  const sc = timing.scenes.find((x) => x.id === id);
  const frame = id === 'ABS' ? Math.round(s * 60) : sc.start + Math.min(sc.frames - 1, Math.round(s * 60 * sc.scale));
  const file = join(outDir, `${id}-${String(s).replace('.', '_')}.png`);
  await renderStill({ composition, serveUrl, output: file, frame, inputProps, imageFormat: 'png' });
  console.log(file, frame);
}
