/** Brass-ring iris: the incoming scene opens through a circle whose rim is a brass guilloché ring. */
export const IrisTransition: React.FC<{ children: React.ReactNode; frames?: number }> = ({ children, frames = IRIS_FRAMES }) => {
  const frame = useCurrentFrame();
  if (frame >= frames) return <AbsoluteFill>{children}</AbsoluteFill>;
  const t = interpolate(frame, [0, frames], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: EASE_IN_OUT });
  const r = t * DIAG;
  const rimOpacity = interpolate(t, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
  return (
    <AbsoluteFill>
      <AbsoluteFill style={{ clipPath: `circle(${r}px at 50% 50%)` }}>{children}</AbsoluteFill>
      <AbsoluteFill style={{ alignItems: 'center', justifyContent: 'center', pointerEvents: 'none' }}>
        <svg width={1920} height={1080} style={{ position: 'absolute', inset: 0 }}>
          <circle cx={960} cy={540} r={r} fill="none" stroke={C.brassHi} strokeWidth={3} opacity={rimOpacity} />
          <circle cx={960} cy={540} r={r + 14} fill="none" stroke={C.brass} strokeWidth={1} opacity={rimOpacity * 0.6} />
        </svg>
        <div style={{ position: 'absolute', opacity: rimOpacity * 0.7, transform: `rotate(${t * 90}deg)` }}>
          <GuillocheRing size={(r + 30) * 2 * 1.25} at={-999} copies={8} lobes={48} amp={1.4} r={40} strokeWidth={0.12} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
import { interpolate, spring } from 'remotion';
import { EASE_IN_OUT, EASE_OUT, FPS, SPRING_STAMP, SPRING_UI } from '../theme';

const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;

/** 0→1 over [at, at+dur] with the house ease-out. */
export const io = (frame: number, at: number, dur = 36, ease = EASE_OUT) =>
  interpolate(frame, [at, at + dur], [0, 1], { ...clamp, easing: ease });
export const inOut = (frame: number, at: number, dur = 48) => io(frame, at, dur, EASE_IN_OUT);
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const springUI = (frame: number, at: number) => spring({ frame: frame - at, fps: FPS, config: SPRING_UI });
export const springStamp = (frame: number, at: number) => spring({ frame: frame - at, fps: FPS, config: SPRING_STAMP });

/** Visible between in and out with fades at both ends: 0→1→0. */
export const window = (frame: number, at: number, out: number, fadeIn = 24, fadeOut = 18) =>
  Math.min(io(frame, at, fadeIn), 1 - io(frame, out - fadeOut, fadeOut, EASE_IN_OUT));

/** Seconds → frames, scaled to the scene's retimed length. */
export const beats = (scale: number) => (sec: number) => Math.round(sec * FPS * scale);
export const sec = (s: number) => Math.round(s * FPS);

