  const frame = useCurrentFrame();
  if (frame < t0) return null;
  const tokens = text.split(/(\s+)/);
  let k = 0;
  return (
    <div style={{ fontFamily: FONT.mono, fontSize: size, lineHeight: 1.45, color, fontWeight: weight, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
