        if (/^\s+$/.test(tok)) return tok;
        const land = t0 + k++ * 2.5;
        if (frame < land) return null;
        const fail = /FAIL/.test(tok);
        const flash = fail ? Math.max(0, 1 - (frame - land) / 18) : 0;
        return (
